/**
 * Types for the CLI-generated `astryx-themes.js`.
 *
 * A sibling `.d.ts` with the same basename types the `.js` directly — an
 * ambient `declare module './astryx-themes'` does not work for a relative
 * specifier.
 *
 * Regenerated by `astryx theme add` / `astryx theme use`.
 */
import type { DefinedTheme } from '@astryxdesign/core/theme';

export declare const themes: Record<string, DefinedTheme>;
export declare const defaultThemeSlug: string;
